import { Controller, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '근태 담당자';

function isNumeric(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isFinite(v);
  }
  if (typeof v === 'string') {
    return /^-?\d+(\.\d+)?$/.test(v.trim());
  }
  return false;
}

function isId(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isInteger(v) && v > 0;
  }
  if (typeof v === 'string') {
    return /^\d+$/.test(v.trim());
  }
  return false;
}

@Controller('api/v1')
export class FnSfr01903Controller {
  @Post('/annual-leaves/:annualLeaveId/adjust')
  @HttpCode(200)
  async adjustAnnualLeave(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const annualLeaveId = req.params['annualLeaveId'];
    if (!isId(annualLeaveId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차 ID가 올바르지 않습니다.');
    }
    if (!isNumeric(data.adjustedDays)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 일수는 숫자여야 합니다.');
    }
    const reason = typeof data.changeReason === 'string' ? data.changeReason.trim() : '';
    if (reason === '') {
      throw new ApiError(422, 'INVALID_LEAVE_ADJUSTMENT', '조정 사유를 입력해 주세요.');
    }
    if (reason.length > 500) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 사유는 500자 이내로 입력해 주세요.');
    }
    const adjustedDays = String(data.adjustedDays).trim();
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT confirm_status AS "confirmStatus",
                granted_days + COALESCE(adjusted_days, 0) + CAST(:adjustedDays AS numeric) - COALESCE(used_days, 0) AS "remainAfter"
           FROM annual_leave
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
            FOR UPDATE`,
        { annualLeaveId, adjustedDays },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '대상 연차를 찾을 수 없습니다.');
      }
      if (found[0].confirmStatus !== '확정') {
        throw new ApiError(422, 'INVALID_LEAVE_ADJUSTMENT', '확정된 연차만 조정할 수 있습니다.');
      }
      if (Number(found[0].remainAfter) < 0) {
        throw new ApiError(422, 'INVALID_LEAVE_ADJUSTMENT', '조정 후 잔여 연차가 음수가 될 수 없습니다.');
      }
      const updated = await db.query(
        `UPDATE annual_leave
            SET adjusted_days = COALESCE(adjusted_days, 0) + CAST(:adjustedDays AS numeric),
                updated_at = now()
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
        RETURNING annual_leave_id AS "annualLeaveId", adjusted_days AS "adjustedDays"`,
        { annualLeaveId, adjustedDays },
      );
      // change_content는 개발 담당자가 정하는 값 (결정)
      await db.execute(
        `INSERT INTO annual_leave_history
           (annual_leave_id, changer_id, change_type, changed_at, change_days, change_content, change_reason, created_at, updated_at)
         VALUES
           (CAST(:annualLeaveId AS bigint), CAST(:userId AS bigint), '조정', now(), CAST(:adjustedDays AS numeric),
            '연차 조정 ' || CAST(:adjustedDays AS text) || '일', :reason, now(), now())`,
        { annualLeaveId, userId: user.id, adjustedDays, reason },
      );
      return updated[0];
    });
  }

  @Post('/annual-leave-settlements')
  @HttpCode(200)
  async createAnnualLeaveSettlement(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (!isId(data.annualLeaveId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차를 선택해 주세요.');
    }
    const baseDate = typeof data.settlementBaseDate === 'string' ? data.settlementBaseDate.trim() : '';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(baseDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '정산 기준일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const annualLeaveId = String(data.annualLeaveId).trim();
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT confirm_status AS "confirmStatus"
           FROM annual_leave
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
            FOR UPDATE`,
        { annualLeaveId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '대상 연차를 찾을 수 없습니다.');
      }
      if (found[0].confirmStatus !== '확정') {
        throw new ApiError(422, 'ANNUAL_LEAVE_NOT_CONFIRMED', '확정되지 않은 연차는 정산할 수 없습니다.');
      }
      const done = await db.query(
        `SELECT annual_leave_settlement_id AS "annualLeaveSettlementId"
           FROM annual_leave_settlement
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)`,
        { annualLeaveId },
      );
      if (done.length > 0) {
        throw new ApiError(409, 'SETTLEMENT_ALREADY_COMPLETED', '이미 정산이 완료된 연차입니다.');
      }
      // 미사용 일수 = 생성 일수(+조정 일수) - 사용 일수. 음수가 되지 않게 0으로 맞춘다 (가정)
      // 정산 금액은 산정 기준(일 통상임금 등)이 입력에 없어 채우지 않는다 (가정: 급여관리 영역에서 반영)
      const rows = await db.query(
        `INSERT INTO annual_leave_settlement
           (annual_leave_id, settlement_base_date, unused_days, settlement_amount, created_at, updated_at)
         SELECT annual_leave_id, CAST(:baseDate AS date),
                GREATEST(granted_days + COALESCE(adjusted_days, 0) - COALESCE(used_days, 0), 0),
                NULL, now(), now()
           FROM annual_leave
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
         RETURNING annual_leave_settlement_id AS "annualLeaveSettlementId",
                   unused_days AS "unusedDays",
                   settlement_amount AS "settlementAmount"`,
        { annualLeaveId, baseDate },
      );
      return rows[0];
    });
  }
}

