import { useState } from 'react';
import {
  call, Badge, Num, DateText, Band, DataTable, Tiles, Drawer, Form, Field,
  TextInput, NumberInput, DateInput, LookupSelect, RefName,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr01903Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [mode, setMode] = useState<'' | 'adjust' | 'settle'>('');
  const [annualLeaveId, setAnnualLeaveId] = useState<number | string>('');
  const [adjustedDays, setAdjustedDays] = useState<number | string>('');
  const [changeReason, setChangeReason] = useState('');
  const [baseDate, setBaseDate] = useState('');

  const open = (next: 'adjust' | 'settle') => {
    setAnnualLeaveId('');
    setAdjustedDays('');
    setChangeReason('');
    setBaseDate('');
    setMode(next);
  };

  const adjustCount = results.filter((r) => r.kind === '조정').length;
  const settleCount = results.filter((r) => r.kind === '정산').length;

  const submitAdjust = async () => {
    if (annualLeaveId === '') {
      throw new Error('연차를 선택해 주세요.');
    }
    if (adjustedDays === '') {
      throw new Error('조정 일수를 입력해 주세요.');
    }
    if (changeReason.trim() === '') {
      throw new Error('조정 사유를 입력해 주세요.');
    }
    const res = await call('POST', `/annual-leaves/${annualLeaveId}/adjust`, role, {
      adjustedDays,
      changeReason: changeReason.trim(),
    });
    setResults([{ kind: '조정', annualLeaveId: res.annualLeaveId, adjustedDays: res.adjustedDays, reason: changeReason.trim() }, ...results]);
    setMode('');
    notify('연차를 조정했습니다.');
  };

  const submitSettle = async () => {
    if (annualLeaveId === '') {
      throw new Error('연차를 선택해 주세요.');
    }
    if (baseDate === '') {
      throw new Error('정산 기준일을 입력해 주세요.');
    }
    const res = await call('POST', '/annual-leave-settlements', role, {
      annualLeaveId,
      settlementBaseDate: baseDate,
    });
    setResults([{ kind: '정산', annualLeaveId, baseDate, unusedDays: res.unusedDays, settlementAmount: res.settlementAmount }, ...results]);
    setMode('');
    notify('연차 정산을 저장했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles items={[
          ['연차 조정', <Num value={adjustCount} />],
          ['연차 정산', <Num value={settleCount} />],
        ]} />
      </section>
      <section className="box span-12">
        <h2>처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => open('adjust')}>연차 조정</button>
          <button type="button" onClick={() => open('settle')}>미사용 연차 정산</button>
        </Band>
        <DataTable
          rows={results}
          empty="이 화면에서 처리한 내역이 없습니다."
          columns={[
            { key: 'kind', label: '구분', render: (r) => <Badge value={r.kind} /> },
            { key: 'annualLeaveId', label: '연차 ID', render: (r) => <RefName table="annual_leave" role={role} value={r.annualLeaveId} /> },
            { key: 'adjustedDays', label: '조정 일수', render: (r) => (r.kind === '조정' ? <Num value={r.adjustedDays} /> : <span>-</span>) },
            { key: 'reason', label: '조정 사유', render: (r) => <span>{String(r.reason ?? '-')}</span> },
            { key: 'baseDate', label: '정산 기준일', render: (r) => (r.kind === '정산' ? <DateText value={r.baseDate} /> : <span>-</span>) },
            { key: 'unusedDays', label: '미사용 연차 일수', render: (r) => (r.kind === '정산' ? <Num value={r.unusedDays} /> : <span>-</span>) },
            { key: 'settlementAmount', label: '정산 금액', render: (r) => (r.kind === '정산' && r.settlementAmount != null ? <Num value={r.settlementAmount} /> : <span>-</span>) },
          ]}
        />
      </section>
      {mode === 'adjust' && (
        <Drawer title="연차 조정" onClose={() => setMode('')}>
          <Form onSubmit={submitAdjust} submit="조정">
            <Field label="연차 ID" required>
              <LookupSelect table="annual_leave" role={role} value={annualLeaveId} onChange={setAnnualLeaveId} />
            </Field>
            <Field label="조정 일수" required hint="가감할 일수 (감소는 음수)">
              <NumberInput value={adjustedDays} onChange={setAdjustedDays} />
            </Field>
            <Field label="조정 사유" required wide>
              <TextInput value={changeReason} onChange={setChangeReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'settle' && (
        <Drawer title="미사용 연차 정산" onClose={() => setMode('')}>
          <Form onSubmit={submitSettle} submit="정산">
            <Field label="연차 ID" required>
              <LookupSelect table="annual_leave" role={role} value={annualLeaveId} onChange={setAnnualLeaveId} />
            </Field>
            <Field label="정산 기준일" required>
              <DateInput value={baseDate} onChange={setBaseDate} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
